 // RF-002: el IVA va incluido en el precio; se informa, no se suma.
-export function calcularFactura(items) {
+// RF-006: descuentoGlobal es un porcentaje entero de 0 a 100 sobre el total de las líneas; el IVA y el neto
+// se calculan sobre el total ya descontado.
+export function calcularFactura(items, { descuentoGlobal = 0 } = {}) {
   if (!Array.isArray(items) || items.length === 0) throw new Error("Una factura necesita al menos una línea");
+  if (!Number.isInteger(descuentoGlobal) || descuentoGlobal < 0 || descuentoGlobal > 100)
+    throw new RangeError("Descuento global inválido: debe ser un porcentaje entero de 0 a 100");
   let totalCentavos = 0;
   for (const item of items) {
     if (!Number.isInteger(item.cantidad) || item.cantidad <= 0) throw new RangeError("Cantidad inválida");
@@ -17,6 +21,7 @@ export function calcularFactura(items) {
       throw new RangeError("Precio inválido: debe estar en centavos enteros");
     totalCentavos += item.cantidad * item.precioUnitarioCentavos;
   }
+  totalCentavos -= Math.round((totalCentavos * descuentoGlobal) / 100);
   const ivaCentavos = Math.round(totalCentavos * TASA_IVA);
   return { totalCentavos, ivaCentavos, netoCentavos: totalCentavos - ivaCentavos };
 }
diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..3926717 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -22,6 +22,25 @@ test("ADR-001: montos en centavos enteros", () => {
   assert.throws(() => calcularFactura([]));
 });

+test("RF-006: descuento global en porcentaje sobre el total", () => {
+  const items = [
+    { cantidad: 2, precioUnitarioCentavos: 5000 },
+    { cantidad: 1, precioUnitarioCentavos: 1050 },
+  ];
+  assert.deepEqual(calcularFactura(items, { descuentoGlobal: 10 }), { totalCentavos: 9945, ivaCentavos: 1293, netoCentavos: 8652 });
+  assert.deepEqual(calcularFactura(items, { descuentoGlobal: 0 }), calcularFactura(items));
+  assert.deepEqual(calcularFactura(items, { descuentoGlobal: 100 }), { totalCentavos: 0, ivaCentavos: 0, netoCentavos: 0 });
+  // redondeo al centavo con Math.round: 5 % de 1050 = 52,5 -> 53
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1050 }], { descuentoGlobal: 5 }).totalCentavos, 997);
+});
+
+test("RF-006: descuento global fuera de rango o no entero se rechaza", () => {
+  const items = [{ cantidad: 1, precioUnitarioCentavos: 1000 }];
+  for (const d of [-1, 101, 10.5, NaN, "10", null]) {
+    assert.throws(() => calcularFactura(items, { descuentoGlobal: d }), RangeError);
+  }
+});
+
